class CartItem {
  constructor(public price:number, public discount:number) {}
}
class Cart { items: CartItem[] = []; add(item:CartItem){ this.items.push(item) }}
class PricingEngine {
  applyPromotions(cart:Cart){
    for (const item of cart.items) {
      if (item.price > 100) item.discount = 20
    }
  }
}

